    22	public class App {
    23	    public static void main(String[] args) {
    24	        Database db = new Database(required("DB_URL"), required("DB_USER"), required("DB_PASSWORD"));
    25	        String port = System.getenv("PORT");
    26	        start(db, port == null || port.isBlank() ? 7070 : Integer.parseInt(port.trim()));
    27	    }
