    29	    /** Monta o sistema. É aqui que se decide quem é avisado de cada coisa que acontece com as reservas. */
    30	    public static Javalin start(Database db, int port) {
    31	        db.migrate();
    32	        RoomRepository rooms = new RoomRepository(db);
    33	        ReservationRepository reservationRepository = new ReservationRepository(db);
    34	        MessageRepository messages = new MessageRepository(db);
    35	
    36	        List<ReservationListener> listeners = List.of(
    37	                new GuestConfirmationEmail(messages),
    38	                new HousekeepingNotifier(messages, "governanca@pousadamarealta.com.br"),
    39	                new FinanceNotifier(messages, "financeiro@pousadamarealta.com.br"));
    40	
    41	        ReservationService reservations = new ReservationService(rooms, reservationRepository, listeners);
    42	        ReportService reports = new ReportService(rooms, reservationRepository);
    43	
    44	        ObjectMapper mapper = new ObjectMapper()
    45	                .registerModule(new JavaTimeModule())
    46	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    47	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    48	        new Routes(rooms, reservations, reports, messages).register(app);
    49	        return app.start(port);
    50	    }
    51	
    52	    private static String required(String name) {
    53	        String value = System.getenv(name);
    54	        if (value == null || value.isBlank()) {
    55	            throw new IllegalStateException("Variável de ambiente ausente: " + name);
    56	        }
    57	        return value;
    58	    }
