    16	import io.javalin.Javalin;
    17	import io.javalin.http.Context;
    18	import io.javalin.http.HttpStatus;
    19	
    20	import java.time.LocalDate;
    21	import java.time.YearMonth;
    22	import java.time.format.DateTimeParseException;
    23	import java.util.regex.Pattern;
    24	
    25	public class Routes {
    26	    private static final String CSV = "text/csv; charset=utf-8";
    27	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    28	    private static final ObjectMapper JSON = new ObjectMapper();
    29	
    30	    private final RoomRepository rooms;
    31	    private final ReservationService reservations;
    32	    private final ReportService reports;
    33	    private final MessageRepository messages;
    34	
    35	    public Routes(RoomRepository rooms, ReservationService reservations, ReportService reports,
    36	                  MessageRepository messages) {
    37	        this.rooms = rooms;
    38	        this.reservations = reservations;
    39	        this.reports = reports;
    40	        this.messages = messages;
    41	    }
    42	
    43	    public void register(Javalin app) {
    44	        app.exception(PousadaException.class, (e, ctx) ->
    45	                ctx.status(e.code().httpStatus()).json(new ErrorJson(e.code().name(), e.getMessage())));
    46	        app.exception(Exception.class, (e, ctx) -> {
    47	            e.printStackTrace();
    48	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR).json(new ErrorJson("INTERNAL_ERROR", "Erro interno"));
    49	        });
    50	
    51	        app.get("/rooms", ctx -> ctx.json(rooms.findAll().stream().map(RoomJson::of).toList()));
    52	
    53	        app.post("/reservations", this::create);
    54	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationJson.of(reservations.get(id(ctx)))));
    55	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(ReservationJson.of(reservations.confirm(id(ctx)))));
    56	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(ReservationJson.of(reservations.cancel(id(ctx)))));
    57	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(ReservationJson.of(reservations.checkIn(id(ctx)))));
    58	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(ReceiptJson.of(reservations.checkOut(id(ctx)))));
    59	        app.get("/reservations/{id}/document", ctx -> ctx.json(ReceiptJson.of(reservations.document(id(ctx)))));
    60	
    61	        app.get("/messages", ctx -> ctx.json(messages.findAll()));
    62	
    63	        app.get("/reports/occupancy", ctx ->
    64	                ctx.contentType(CSV).result(reports.occupancy(date(ctx.queryParam("date"), "date"))));
    65	        app.get("/reports/revenue", ctx ->
    66	                ctx.contentType(CSV).result(reports.revenue(month(ctx.queryParam("month")))));
    67	    }
    68	
    69	    private void create(Context ctx) {
    70	        JsonNode body;
    71	        try {
    72	            body = JSON.readTree(ctx.body());
    73	        } catch (Exception e) {
    74	            throw invalid("O corpo precisa ser um JSON válido");
    75	        }
    76	        if (body == null || !body.isObject()) {
    77	            throw invalid("O corpo precisa ser um objeto JSON");
    78	        }
    79	        var reservation = reservations.create(
    80	                integer(body, "roomNumber"), text(body, "guestName"), text(body, "guestEmail"),
    81	                text(body, "guestCpf"), date(text(body, "checkIn"), "checkIn"), date(text(body, "checkOut"), "checkOut"),
    82	                integer(body, "guests"), ratePlan(text(body, "ratePlan")));
    83	        ctx.status(HttpStatus.CREATED).json(ReservationJson.of(reservation));
    84	    }
    85	
    86	    private static long id(Context ctx) {
    87	        try {
    88	            return Long.parseLong(ctx.pathParam("id"));
    89	        } catch (NumberFormatException e) {
    90	            throw new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada");
    91	        }
    92	    }
    93	
    94	    private static String text(JsonNode body, String field) {
    95	        JsonNode node = body.get(field);
    96	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    97	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    98	        }
    99	        return node.asText();
   100	    }
   101	
   102	    private static int integer(JsonNode body, String field) {
   103	        JsonNode node = body.get(field);
   104	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
   105	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
   106	        }
   107	        return node.asInt();
   108	    }
   109	
   110	    private static RatePlan ratePlan(String value) {
   111	        try {
   112	            return RatePlan.valueOf(value);
   113	        } catch (IllegalArgumentException e) {
   114	            throw invalid("Plano de tarifa inválido: " + value);
   115	        }
   116	    }
   117	
   118	    private static LocalDate date(String value, String field) {
   119	        try {
   120	            if (value == null) {
   121	                throw invalid("Data ausente: " + field);
   122	            }
   123	            return LocalDate.parse(value);
   124	        } catch (DateTimeParseException e) {
   125	            throw invalid("Data fora do formato AAAA-MM-DD: " + field);
   126	        }
   127	    }
   128	
   129	    private static YearMonth month(String value) {
   130	        try {
   131	            if (value == null || !MONTH.matcher(value).matches()) {
   132	                throw invalid("Mês fora do formato AAAA-MM");
   133	            }
   134	            return YearMonth.parse(value);
   135	        } catch (DateTimeParseException e) {
   136	            throw invalid("Mês fora do formato AAAA-MM");
   137	        }
   138	    }
   139	
   140	    private static PousadaException invalid(String message) {
   141	        return new PousadaException(ErrorCode.INVALID_REQUEST, message);
   142	    }
   143	}
