    13	public class ReportService {
    14	    private final RoomRepository rooms;
    15	    private final ReservationRepository reservations;
    16	
    17	    public ReportService(RoomRepository rooms, ReservationRepository reservations) {
    18	        this.rooms = rooms;
    19	        this.reservations = reservations;
    20	    }
    21	
    22	    public String occupancy(LocalDate night) {
    23	        List<Reservation> occupying = reservations.findPaidOccupying(night);
    24	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    25	        for (Reservation r : occupying) {
    26	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
    27	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    28	        }
    29	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    30	        return csv.append("total,").append(occupiedRooms).append('/').append(rooms.findAll().size()).append('\n')
    31	                .toString();
    32	    }
    33	
    34	    public String revenue(YearMonth month) {
    35	        List<Reservation> starting = reservations.findKeptMoneyStartingBetween(
    36	                month.atDay(1), month.plusMonths(1).atDay(1));
    37	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    38	        BigDecimal total = Money.ZERO;
    39	        for (Reservation r : starting) {
    40	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
    41	                    .append(r.checkOut()).append(',').append(r.status()).append(',').append(r.amountKept()).append('\n');
    42	            total = total.add(r.amountKept());
    43	        }
    44	        return csv.append("total,").append(total).append('\n').toString();
    45	    }
    46	}
