    10	import br.com.marealta.pousada.notification.ReservationListener;
    11	import br.com.marealta.pousada.persistence.ReservationRepository;
    12	import br.com.marealta.pousada.persistence.RoomRepository;
    13	
    14	import java.time.LocalDate;
    15	import java.util.List;
    16	import java.util.function.Consumer;
    17	
    18	public class ReservationService {
    19	    private final RoomRepository rooms;
    20	    private final ReservationRepository reservations;
    21	    private final List<ReservationListener> listeners;
    22	
    23	    public ReservationService(RoomRepository rooms, ReservationRepository reservations,
    24	                              List<ReservationListener> listeners) {
    25	        this.rooms = rooms;
    26	        this.reservations = reservations;
    27	        this.listeners = List.copyOf(listeners);
    28	    }
    29	
    30	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    31	                              LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    32	        if (guests < 1 || !checkOut.isAfter(checkIn)) {
    33	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "Datas ou número de hóspedes inválidos");
    34	        }
    35	        Room room = rooms.findByNumber(roomNumber)
    36	                .orElseThrow(() -> new PousadaException(ErrorCode.ROOM_NOT_FOUND, "Quarto não encontrado: " + roomNumber));
    37	        Reservation reservation = Reservation.create(room, guestName, guestEmail, guestCpf,
    38	                checkIn, checkOut, guests, ratePlan);
    39	        reservations.insertIfAvailable(reservation);
    40	        return reservation;
    41	    }
    42	
    43	    public Reservation confirm(long id) {
    44	        Reservation r = get(id);
    45	        ReservationStatus previous = r.status();
    46	        r.confirm();
    47	        save(r, previous);
    48	        listeners.forEach(l -> l.onConfirmed(r));
    49	        return r;
    50	    }
    51	
    52	    public Reservation cancel(long id) {
    53	        Reservation r = get(id);
    54	        ReservationStatus previous = r.status();
    55	        r.cancel();
    56	        save(r, previous);
    57	        listeners.forEach(l -> l.onCancelled(r, previous));
    58	        return r;
    59	    }
    60	
    61	    public Reservation checkIn(long id) {
    62	        return transition(id, Reservation::startStay);
    63	    }
    64	
    65	    public Receipt checkOut(long id) {
    66	        return transition(id, Reservation::endStay).receipt();
    67	    }
    68	
    69	    public Receipt document(long id) {
    70	        return get(id).receipt();
    71	    }
    72	
    73	    public Reservation get(long id) {
    74	        return reservations.findById(id)
    75	                .orElseThrow(() -> new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada: " + id));
    76	    }
    77	
    78	    private Reservation transition(long id, Consumer<Reservation> change) {
    79	        Reservation r = get(id);
    80	        ReservationStatus previous = r.status();
    81	        change.accept(r);
    82	        save(r, previous);
    83	        return r;
    84	    }
    85	
    86	    private void save(Reservation r, ReservationStatus previous) {
    87	        if (!reservations.update(r, previous)) {
    88	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    89	                    "A situação da reserva mudou enquanto a operação era feita");
    90	        }
    91	    }
    92	}
