     1	package br.com.marealta.pousada.notification;
     2	
     3	import br.com.marealta.pousada.domain.Reservation;
     4	import br.com.marealta.pousada.domain.ReservationStatus;
     5	
     6	/**
     7	 * Quem quer saber o que acontece com as reservas. Cada interessado implementa só os eventos que lhe importam
     8	 * e decide sozinho se age.
     9	 */
    10	public interface ReservationListener {
    11	
    12	    default void onConfirmed(Reservation reservation) {
    13	    }
