    30	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    31	                              LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    32	        if (guests < 1 || !checkOut.isAfter(checkIn)) {
    33	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "Datas ou número de hóspedes inválidos");
    34	        }
    35	        Room room = rooms.findByNumber(roomNumber)
    36	                .orElseThrow(() -> new PousadaException(ErrorCode.ROOM_NOT_FOUND, "Quarto não encontrado: " + roomNumber));
    37	        Reservation reservation = Reservation.create(room, guestName, guestEmail, guestCpf,
    38	                checkIn, checkOut, guests, ratePlan);
    39	        reservations.insertIfAvailable(reservation);
    40	        return reservation;
    41	    }
