    43	    public Reservation confirm(long id) {
    44	        Reservation r = get(id);
    45	        ReservationStatus previous = r.status();
    46	        r.confirm();
    47	        save(r, previous);
    48	        listeners.forEach(l -> l.onConfirmed(r));
    49	        return r;
