     9	
    10	    private Pricing() {
    11	    }
    12	
    13	    /** 15 de dezembro até o fim de fevereiro, e julho inteiro. */
    14	    public static boolean isHighSeason(LocalDate night) {
    15	        int month = night.getMonthValue();
    16	        return (month == 12 && night.getDayOfMonth() >= 15) || month == 1 || month == 2 || month == 7;
    17	    }
    18	
    19	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    20	        BigDecimal rate = room.nightlyRate();
    21	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    22	    }
    23	
    24	    /** Soma das noites de checkIn (inclusive) a checkOut (exclusive). */
    25	    public static BigDecimal subtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    26	        BigDecimal sum = Money.ZERO;
    27	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    28	            sum = sum.add(nightPrice(room, night));
    29	        }
    30	        return sum;
    31	    }
