    10	
    11	/** Conexões com o PostgreSQL e criação do que o sistema precisa. */
    12	public class Database {
    13	    private static final Map<Integer, RoomType> ROOMS = Map.of(
    14	            101, RoomType.STANDARD, 102, RoomType.STANDARD,
    15	            201, RoomType.DELUXE, 202, RoomType.DELUXE,
    16	            301, RoomType.SUITE);
    17	
    18	    private final String url;
    19	    private final String user;
    20	    private final String password;
    21	
    22	    public Database(String url, String user, String password) {
    23	        this.url = url;
    24	        this.user = user;
    25	        this.password = password;
    26	    }
    27	
    28	    public Connection connect() throws SQLException {
    29	        return DriverManager.getConnection(url, user, password);
    30	    }
    31	
    32	    public void migrate() {
    33	        try (Connection c = connect(); Statement s = c.createStatement()) {
    34	            // Evita que duas instâncias subindo juntas disputem a criação das tabelas.
    35	            c.setAutoCommit(false);
    36	            s.execute("SELECT pg_advisory_xact_lock(7070001)");
    37	            s.execute("""
    38	                    CREATE TABLE IF NOT EXISTS rooms (
    39	                        number INTEGER PRIMARY KEY,
    40	                        type   VARCHAR(20) NOT NULL
    41	                    )""");
    42	            s.execute("""
    43	                    CREATE TABLE IF NOT EXISTS reservations (
    44	                        id           BIGSERIAL PRIMARY KEY,
    45	                        room_number  INTEGER NOT NULL REFERENCES rooms(number),
    46	                        guest_name   TEXT NOT NULL,
    47	                        guest_email  TEXT NOT NULL,
    48	                        guest_cpf    TEXT NOT NULL,
    49	                        check_in     DATE NOT NULL,
    50	                        check_out    DATE NOT NULL,
    51	                        guests       INTEGER NOT NULL,
    52	                        rate_plan    VARCHAR(20) NOT NULL,
    53	                        subtotal     NUMERIC(12,2) NOT NULL,
    54	                        discount     NUMERIC(12,2) NOT NULL,
    55	                        total        NUMERIC(12,2) NOT NULL,
    56	                        status       VARCHAR(20) NOT NULL,
    57	                        amount_paid  NUMERIC(12,2) NOT NULL,
    58	                        refund       NUMERIC(12,2)
    59	                    )""");
    60	            s.execute("""
    61	                    CREATE TABLE IF NOT EXISTS messages (
    62	                        id       BIGSERIAL PRIMARY KEY,
    63	                        channel  VARCHAR(20) NOT NULL,
    64	                        recipient TEXT NOT NULL,
    65	                        subject  TEXT NOT NULL,
    66	                        body     TEXT NOT NULL
    67	                    )""");
    68	            ROOMS.forEach((number, type) -> {
    69	                try {
    70	                    s.execute("INSERT INTO rooms (number, type) VALUES (" + number + ", '" + type.name()
    71	                            + "') ON CONFLICT (number) DO NOTHING");
    72	                } catch (SQLException e) {
    73	                    throw new IllegalStateException(e);
    74	                }
    75	            });
    76	            c.commit();
    77	        } catch (SQLException e) {
    78	            throw new IllegalStateException("Falha ao preparar o banco de dados", e);
    79	        }
    80	    }
    81	}
