    91	    /** Grava a mudança só se a reserva ainda estiver na situação em que foi lida. */
    92	    public boolean update(Reservation r, ReservationStatus expectedStatus) {
    93	        try (Connection c = db.connect();
    94	             PreparedStatement ps = c.prepareStatement(
    95	                     "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ? AND status = ?")) {
    96	            ps.setString(1, r.status().name());
    97	            ps.setBigDecimal(2, r.amountPaid());
    98	            ps.setBigDecimal(3, r.refund());
    99	            ps.setLong(4, r.id());
   100	            ps.setString(5, expectedStatus.name());
   101	            return ps.executeUpdate() == 1;
   102	        } catch (SQLException e) {
   103	            throw new IllegalStateException(e);
   104	        }
   105	    }
   106	
   107	    public Optional<Reservation> findById(long id) {
   108	        List<Reservation> found = query(SELECT + "WHERE r.id = ?", ps -> ps.setLong(1, id));
   109	        return found.stream().findFirst();
   110	    }
   111	
   112	    /** Reservas pagas (não pendentes nem canceladas) que ocupam um quarto na noite dada. */
   113	    public List<Reservation> findPaidOccupying(LocalDate night) {
   114	        return query(SELECT + "WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
   115	                + "AND r.check_in <= ? AND r.check_out > ? ORDER BY r.room_number, r.id", ps -> {
   116	            ps.setDate(1, Date.valueOf(night));
   117	            ps.setDate(2, Date.valueOf(night));
   118	        });
   119	    }
   120	
   121	    /** Reservas que começam no intervalo [from, to) e deixaram dinheiro com a pousada. */
   122	    public List<Reservation> findKeptMoneyStartingBetween(LocalDate from, LocalDate to) {
   123	        return query(SELECT + "WHERE r.check_in >= ? AND r.check_in < ? "
   124	                + "AND r.amount_paid - COALESCE(r.refund, 0) > 0 ORDER BY r.check_in, r.id", ps -> {
   125	            ps.setDate(1, Date.valueOf(from));
   126	            ps.setDate(2, Date.valueOf(to));
   127	        });
