   135	        try (Connection c = db.connect(); PreparedStatement ps = c.prepareStatement(sql)) {
   136	            binder.bind(ps);
   137	            try (ResultSet rs = ps.executeQuery()) {
   138	                List<Reservation> list = new ArrayList<>();
   139	                while (rs.next()) {
