    21	public class ReservationRepository {
    22	    private static final String SELECT = """
    23	            SELECT r.*, rm.type AS room_type FROM reservations r
    24	            JOIN rooms rm ON rm.number = r.room_number
    25	            """;
    26	
    27	    private final Database db;
    28	
    29	    public ReservationRepository(Database db) {
    30	        this.db = db;
    31	    }
    32	
    33	    /** Grava a reserva nova se o quarto estiver livre em todas as noites; senão, ROOM_UNAVAILABLE. */
    34	    public void insertIfAvailable(Reservation r) {
    35	        try (Connection c = db.connect()) {
    36	            c.setAutoCommit(false);
    37	            try {
    38	                // Trava o quarto para que duas reservas simultâneas não passem juntas pela verificação.
    39	                try (PreparedStatement lock = c.prepareStatement("SELECT 1 FROM rooms WHERE number = ? FOR UPDATE")) {
    40	                    lock.setInt(1, r.room().number());
    41	                    lock.executeQuery().close();
    42	                }
    43	                try (PreparedStatement overlap = c.prepareStatement("""
    44	                        SELECT 1 FROM reservations
    45	                        WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    46	                        LIMIT 1""")) {
    47	                    overlap.setInt(1, r.room().number());
    48	                    overlap.setDate(2, Date.valueOf(r.checkOut()));
    49	                    overlap.setDate(3, Date.valueOf(r.checkIn()));
    50	                    try (ResultSet rs = overlap.executeQuery()) {
    51	                        if (rs.next()) {
    52	                            throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE,
    53	                                    "O quarto " + r.room().number() + " já está reservado em alguma das noites pedidas");
    54	                        }
    55	                    }
    56	                }
    57	                try (PreparedStatement ps = c.prepareStatement("""
    58	                        INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    59	                            guests, rate_plan, subtotal, discount, total, status, amount_paid, refund)
    60	                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
    61	                    ps.setInt(1, r.room().number());
    62	                    ps.setString(2, r.guestName());
    63	                    ps.setString(3, r.guestEmail());
    64	                    ps.setString(4, r.guestCpf());
    65	                    ps.setDate(5, Date.valueOf(r.checkIn()));
    66	                    ps.setDate(6, Date.valueOf(r.checkOut()));
    67	                    ps.setInt(7, r.guests());
    68	                    ps.setString(8, r.ratePlan().name());
    69	                    ps.setBigDecimal(9, r.subtotal());
    70	                    ps.setBigDecimal(10, r.discount());
    71	                    ps.setBigDecimal(11, r.total());
    72	                    ps.setString(12, r.status().name());
    73	                    ps.setBigDecimal(13, r.amountPaid());
    74	                    ps.setBigDecimal(14, r.refund());
    75	                    ps.executeUpdate();
    76	                    try (ResultSet keys = ps.getGeneratedKeys()) {
    77	                        keys.next();
    78	                        r.assignId(keys.getLong(1));
    79	                    }
    80	                }
    81	                c.commit();
    82	            } catch (RuntimeException | SQLException e) {
    83	                c.rollback();
    84	                throw e;
    85	            }
    86	        } catch (SQLException e) {
    87	            throw new IllegalStateException(e);
    88	        }
    89	    }
