   134	    private List<Reservation> query(String sql, Binder binder) {
   135	        try (Connection c = db.connect(); PreparedStatement ps = c.prepareStatement(sql)) {
   136	            binder.bind(ps);
   137	            try (ResultSet rs = ps.executeQuery()) {
   138	                List<Reservation> list = new ArrayList<>();
   139	                while (rs.next()) {
   140	                    list.add(map(rs));
   141	                }
   142	                return list;
   143	            }
   144	        } catch (SQLException e) {
   145	            throw new IllegalStateException(e);
   146	        }
   147	    }
