  9	import static org.junit.jupiter.api.Assertions.*;
 10	
 11	class DomainTest {
 12	    private static final Room STANDARD = new Room(101, RoomType.STANDARD);
 13	    private static final Room DELUXE = new Room(201, RoomType.DELUXE);
 14	
 15	    private static Reservation reserve(Room room, String in, String out, int guests, RatePlan plan) {
 16	        return Reservation.create(room, "Carla Dias", "carla@example.com", "111.222.333-44",
 17	                LocalDate.parse(in), LocalDate.parse(out), guests, plan);
 18	    }
 19	
 20	    @Test
 21	    void highSeasonNightsCostTwentyPercentMore() {
 22	        Reservation r = reserve(STANDARD, "2027-07-10", "2027-07-12", 2, RatePlan.STANDARD);
 23	        assertEquals(new BigDecimal("599.76"), r.total());
 24	        assertEquals(2, r.nights());
 25	    }
 26	
 27	    @Test
 28	    void seasonBoundaries() {
 29	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
 30	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
 31	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
 32	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2028-03-01")));
 33	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-06-30")));
 34	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-07-31")));
 35	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-08-01")));
 36	    }
 37	
 38	    @Test
 39	    void nonRefundableDiscountsFifteenPercentHalfEven() {
 40	        Reservation r = reserve(STANDARD, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE);
 41	        assertEquals(new BigDecimal("249.90"), r.subtotal());
 42	        assertEquals(new BigDecimal("37.48"), r.discount()); // 37.485 -> par
 43	        assertEquals(new BigDecimal("212.42"), r.total());
 44	    }
 45	
 46	    @Test
 47	    void moneyAndDateFormatting() {
 48	        assertEquals("R$ 1.234,56", Money.brl(new BigDecimal("1234.56")));
 49	        assertEquals("R$ 0,00", Money.brl(BigDecimal.ZERO));
 50	        assertEquals("10/03/2027", Money.brDate(LocalDate.parse("2027-03-10")));
 51	    }
 52	
 53	    @Test
 54	    void receiptText() {
 55	        Reservation r = new Reservation(7, DELUXE, "Carla Dias", "c@x.com", "111.222.333-44",
 56	                LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, RatePlan.STANDARD,
 57	                new BigDecimal("779.80"), Money.ZERO, new BigDecimal("779.80"), ReservationStatus.CONFIRMED,
 58	                new BigDecimal("779.80"), null);
 59	        assertEquals("""
 60	                Comprovante de reserva nº 7
 61	                Hóspede: Carla Dias (CPF 111.222.333-44)
 62	                Quarto: 201 (DELUXE)
 63	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
 64	                Diárias: R$ 779,80
 65	                Total: R$ 779,80""", r.receipt().text());
 66	    }
 67	
 68	    @Test
 69	    void receiptWithDiscountAndSingleNight() {
 70	        Reservation r = reserve(STANDARD, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE);
 71	        r.assignId(3);
 72	        r.confirm();
 73	        String text = r.receipt().text();
 74	        assertTrue(text.contains("| 1 diária\n"));
 75	        assertTrue(text.contains("Desconto: R$ 37,48\nTotal: R$ 212,42"));
 76	    }
 77	
 78	    @Test
 79	    void lifecycleAndRefunds() {
 80	        Reservation pending = reserve(STANDARD, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD);
 81	        assertThrows(PousadaException.class, pending::startStay);
 82	        assertThrows(PousadaException.class, pending::receipt);
 83	        pending.cancel();
 84	        assertEquals(Money.ZERO, pending.refund());
 85	
 86	        Reservation paid = reserve(STANDARD, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD);
 87	        paid.confirm();
 88	        assertEquals(paid.total(), paid.amountPaid());
 89	        paid.cancel();
 90	        assertEquals(paid.total(), paid.refund());
 91	        assertEquals(Money.ZERO, paid.amountKept());
 92	
 93	        Reservation locked = reserve(STANDARD, "2027-03-10", "2027-03-12", 1, RatePlan.NON_REFUNDABLE);
 94	        locked.confirm();
 95	        locked.cancel();
 96	        assertEquals(Money.ZERO, locked.refund());
 97	        assertEquals(locked.total(), locked.amountKept());
 98	
 99	        Reservation stay = reserve(STANDARD, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD);
100	        stay.confirm();
101	        stay.startStay();
102	        assertThrows(PousadaException.class, stay::cancel);
103	        assertThrows(PousadaException.class, stay::confirm);
104	        stay.endStay();
105	        assertThrows(PousadaException.class, stay::endStay);
106	    }
107	
108	    @Test
109	    void capacityAndGuestsValidation() {
110	        PousadaException e = assertThrows(PousadaException.class,
111	                () -> reserve(STANDARD, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD));
112	        assertEquals(ErrorCode.CAPACITY_EXCEEDED, e.code());
113	        e = assertThrows(PousadaException.class,
114	                () -> reserve(STANDARD, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD));
115	        assertEquals(ErrorCode.INVALID_REQUEST, e.code());
116	    }
117	}
