272	    void cancellationNotifications() throws Exception {
273	        int before = JSON.readTree(call("GET", "/messages", null).body()).size();
274	
275	        // pendente cancelada: ninguém é avisado
276	        long pending = JSON.readTree(call("POST", "/reservations", reservation(301, "2027-08-01", "2027-08-03", 4, "STANDARD")).body()).get("id").asLong();
277	        JsonNode cancelled = JSON.readTree(call("POST", "/reservations/" + pending + "/cancellation", null).body());
278	        assertEquals("CANCELLED", cancelled.get("status").asText());
279	        assertEquals(0.0, cancelled.get("refund").asDouble());
280	        assertEquals(before, JSON.readTree(call("GET", "/messages", null).body()).size());
281	        // quarto liberado
282	        assertEquals(201, call("POST", "/reservations", reservation(301, "2027-08-01", "2027-08-03", 4, "STANDARD")).statusCode());
283	
284	        // confirmada, plano normal: governança e financeiro
285	        long refundable = JSON.readTree(call("POST", "/reservations", reservation(102, "2027-08-01", "2027-08-03", 2, "STANDARD")).body()).get("id").asLong();
286	        call("POST", "/reservations/" + refundable + "/confirmation", null);
287	        int mid = JSON.readTree(call("GET", "/messages", null).body()).size();
288	        call("POST", "/reservations/" + refundable + "/cancellation", null);
289	        JsonNode msgs = JSON.readTree(call("GET", "/messages", null).body());
290	        assertEquals(mid + 2, msgs.size());
291	        StringBuilder subjects = new StringBuilder();
292	        for (int i = mid; i < msgs.size(); i++) subjects.append(msgs.get(i).get("subject").asText()).append('|');
293	        assertTrue(subjects.toString().contains("Reserva cancelada - quarto 102"));
294	        assertTrue(subjects.toString().contains("Reembolso - reserva " + refundable));
295	
296	        // confirmada, não reembolsável: só a governança
297	        long locked = JSON.readTree(call("POST", "/reservations", reservation(101, "2027-08-01", "2027-08-03", 2, "NON_REFUNDABLE")).body()).get("id").asLong();
298	        call("POST", "/reservations/" + locked + "/confirmation", null);
299	        int mid2 = JSON.readTree(call("GET", "/messages", null).body()).size();
300	        JsonNode lockedCancelled = JSON.readTree(call("POST", "/reservations/" + locked + "/cancellation", null).body());
301	        assertEquals(0.0, lockedCancelled.get("refund").asDouble());
302	        assertEquals(mid2 + 1, JSON.readTree(call("GET", "/messages", null).body()).size());
303	        // o dinheiro retido continua no financeiro
304	        String revenue = call("GET", "/reports/revenue?month=2027-08", null).body();
305	        assertTrue(revenue.contains(locked + ",101,2027-08-01,2027-08-03,CANCELLED,"));
306	        assertFalse(revenue.contains("," + refundable + ","));
307	    }
